  function icon(name) {
    if (!name) return null;
    if (/^https?:\/\//i.test(name)) return name;
    return `${CDN}${String(name).replace(/\.jpg$/i, "")}.jpg`;
  }

  function bossIcon(slug) {
    if (!slug) return null;
    if (/^https?:\/\//i.test(slug)) return slug;
    return `${BOSS_CDN}ui-ej-boss-${String(slug).replace(/\.png$/i, "")}.png`;
  }

  function ev(partial) {
    const out = { ...partial };
    if (out.icon && !out.iconUrl) out.iconUrl = icon(out.icon);
    delete out.icon;
    return out;
  }

